docker exec clearcaseiq-prod-api sh -lc 'cat > /tmp/ic.cjs <<"EOF"
const { PrismaClient } = require(require.resolve("@prisma/client", { paths: ["/app", "/app/api"] })); const prisma = new PrismaClient();
const ini = (n) => (n ? String(n).split(/\s+/).map((p) => p[0] + ".").join("") : "-");
(async () => {
  const since = new Date(Date.now() - 3 * 3600 * 1000);
  const files = await prisma.evidenceFile.findMany({ where: { createdAt: { gte: since } }, orderBy: { createdAt: "desc" }, take: 30, select: { id: true, createdAt: true, category: true, subcategory: true, uploadMethod: true, mimetype: true, processingStatus: true, identityCheck: true, assessmentId: true, ocrText: true } });
  console.log("OCR_PROVIDER=" + (process.env.OCR_PROVIDER || "(unset)") + " ENABLE_OCR=" + (process.env.ENABLE_OCR || "(unset)"));
  for (const f of files) {
    let ic = null; try { ic = JSON.parse(f.identityCheck || "null"); } catch {}
    console.log([f.createdAt.toISOString(), f.category + "/" + (f.subcategory || "-"), "via=" + (f.uploadMethod || "-"), f.mimetype, "proc=" + f.processingStatus, "ocrChars=" + (f.ocrText ? f.ocrText.length : 0), "verdict=" + (ic ? ic.verdict : "NONE"), "reason=" + (ic && ic.reason || "-"), "doc=" + ini(ic && ic.documentName), "claimant=" + ini(ic && ic.claimantName), "case=" + (f.assessmentId || "-").slice(-6)].join(" | "));
  }
  process.exit(0);
})().catch((e) => { console.error("ERR", e.message); process.exit(1); });
EOF
cd /app && node /tmp/ic.cjs; rm -f /tmp/ic.cjs'
